"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["60509"],{11165(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.peso_area_enem.corte_negativo","status":422,"titulo":"Corte de \xe1rea n\xe3o pode ser negativo"},"descricao":{"codigo":"uniplus.configuracao.peso_area_enem.corte_negativo","requisitos":[],"oQueAconteceu":["Um item da lista `areas` traz um corte menor que zero. O corte \xe9 a nota m\xednima da \xe1rea, que o Anexo I da Resolu\xe7\xe3o n\xba 805/2024/Consepe, da Unifesspa, pode fixar para cada grupo, e \xe9 opcional: sem corte, a \xe1rea n\xe3o tem nota m\xednima. Quando informado, vai de zero a 1.000, a escala das notas do ENEM.","A recusa vem na lista `errors` da resposta, com `field` igual a `areas[i].corte`, em que `i` \xe9 a posi\xe7\xe3o do item recusado na lista, come\xe7ando em zero, e a mensagem cita o nome da \xe1rea. As demais recusas do corpo v\xeam na mesma resposta, e nada \xe9 gravado. Na atualiza\xe7\xe3o, o corpo \xe9 conferido antes da busca da linha: um `{id}` que n\xe3o existe s\xf3 responde como n\xe3o encontrado quando o corpo \xe9 v\xe1lido."],"comoResolver":["Informe um corte de zero a 1.000, ou omita o campo para a \xe1rea ficar sem corte, e envie de novo."],"ondeAparece":["Cadastro dos pesos por \xe1rea do ENEM","Atualiza\xe7\xe3o dos pesos por \xe1rea do ENEM"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Peso area enem"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);